const params = $input.first().json.query || {};
const challenge = params['hub.challenge'] || '';
const verifyToken = params['hub.verify_token'] || '';
const expectedToken = 'livskin_wa_webhook_2026';
if (verifyToken === expectedToken && challenge) {
  return [{ json: { response: challenge, statusCode: 200 } }];
} else {
  return [{ json: { response: 'forbidden', statusCode: 403 } }];
}

// === Yossie HANDOFF: extrae datos del inbound + decide acción ===
// Solo procesa inbounds de tipo 'messages' (NO status callbacks)

const REFERRAL_PRODUCT_PATTERNS = {
  botox: /\b(botox|toxina|arrugas|expresi[óo]n|tercio|patas\s+de\s+gallo|entrecejo|frente)\b/i,
  acido: /(\b(acido|[áa]cido)\s+(hialuronico|hialur[óo]nico)\b)|\bhialur[óo]nico\b|\brinomodelaci[óo]n\b|\bpomulos\b|\blabios\b|\bmentón\b/i,
  prp: /\b(prp|plasma|plaquetas)\b/i,
  limpieza: /(limpieza\s+facial|facial\s+profunda)/i,
};

function detectProduct(text) {
  if (!text) return null;
  for (const [p, re] of Object.entries(REFERRAL_PRODUCT_PATTERNS)) {
    if (re.test(text)) return p;
  }
  return null;
}

const PRODUCT_LABELS = {
  botox: 'Botox (S/250 zona / S/700 full face)',
  acido: 'Ácido Hialurónico (rinomodelación / ojeras / pómulos / labios / mentón)',
  prp: 'Plasma Rico en Plaquetas - PRP (S/220 sesión)',
  limpieza: 'Limpieza Facial Profunda (S/70-120)',
};

const body = $input.first().json.body || {};
const entries = body.entry || [];
const outputs = [];

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const value = change.value || {};
    const messages = value.messages || [];
    const contacts = value.contacts || [];

    // Skip status callbacks (sent/delivered/read) — solo procesar mensajes reales
    if (!messages.length) continue;

    for (const msg of messages) {
      const from = msg.from;
      const messageId = msg.id;
      const timestamp = msg.timestamp;
      const type = msg.type;
      let bodyText = '';
      if (type === 'text') bodyText = msg.text?.body || '';
      else if (type === 'button') bodyText = msg.button?.text || '';
      else if (type === 'interactive') bodyText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
      else if (type === 'image') bodyText = '[imagen] ' + (msg.image?.caption || '');
      else if (type === 'audio') bodyText = '[audio]';
      else if (type === 'document') bodyText = '[documento] ' + (msg.document?.filename || '');
      else if (type === 'location') bodyText = `[ubicación] ${msg.location?.latitude},${msg.location?.longitude}`;
      else bodyText = `[${type}]`;

      const contact = contacts.find(c => c.wa_id === from) || {};
      const profileName = contact.profile?.name || '';

      const referral = msg.referral || msg.context?.referral || null;
      const product = detectProduct(referral ? (referral.headline + ' ' + (referral.body || '')) : bodyText);
      const productLabel = product ? PRODUCT_LABELS[product] : 'No detectado';

      // Phone E.164 (Meta da sin +)
      const phoneE164 = from.startsWith('+') ? from : '+' + from;

      // Notif a Dario
      const notifText = `🆕 LEAD NUEVO en Livskin\n\n` +
        `📱 Phone: ${phoneE164}\n` +
        `👤 Nombre (perfil WA): ${profileName || '(sin perfil)'}\n` +
        `🎯 Producto del ad: ${productLabel}\n` +
        (referral ? `🔗 Ad source: ${referral.headline || ''}\n   ID: ${referral.source_id || referral.source_url || 'n/a'}\n` : `🔗 Ad source: contacto directo (no via ad)\n`) +
        `\n💬 Mensaje del lead:\n"${bodyText}"\n\n` +
        `👉 Responde directamente al lead desde tu WhatsApp personal: wa.me/${phoneE164.replace('+','')}`;

      // Copy respuesta al lead
      const leadResponse = `Hola ${profileName || ''} ☺️\n\nGracias por escribirnos a Livskin. Soy Yossie, asistente de la Dra. Claudia.\n\nTe paso con Dario que coordina las citas — te responde en breve por aquí.`;

      outputs.push({
        json: {
          // Para el dispatch
          from,
          phone_e164: phoneE164,
          profile_name: profileName,
          messageId,
          timestamp,
          type,
          inbound_text: bodyText,
          referral_product: product,
          referral_source_id: referral?.source_id || null,
          referral_source_url: referral?.source_url || null,
          referral_headline: referral?.headline || null,
          referral_body: referral?.body || null,
          phone_number_id: value.metadata?.phone_number_id,

          // Para A1 webhook (Vtiger Lead create)
          // NOTA: NO usar _source='wa-click' (eso es patch para landing-click sin phone).
          // Para WA inbound directo queremos que A1 guarde el phone.
          vtiger_payload: {
            phone: phoneE164,
            nombre: profileName || `Lead WA ${phoneE164.slice(-4)}`,
            email: '',
            _source: 'wa-inbound',
            utm_source: referral ? 'facebook' : 'wa-direct',
            utm_medium: referral ? 'cpc' : 'organic',
            utm_campaign: referral?.source_id || 'wa-direct-may26',
            utm_content: product || 'unknown',
            event_id: referral?.source_id || messageId,
            landing_url: referral?.source_url || '',
            tratamiento_interes: product ? PRODUCT_LABELS[product] : 'Otro / No especificado',
          },

          // Para Yossie response al lead
          lead_response_text: leadResponse,

          // Para notif a Dario
          dario_notif_text: notifText,
          dario_phone: '51982732978',  // Sin + porque Meta API lo quiere así
        }
      });

      console.log(`[D1-HANDOFF] from=${from} (${profileName}) product=${product} msgId=${messageId}`);
    }
  }
}

return outputs.length > 0 ? outputs : [{ json: { skip: true } }];

